typedef __UINTPTR_TYPE__ word;
typedef unsigned (*callable)(unsigned);
__attribute__((micromips,noinline,aligned(16))) unsigned target(unsigned x) { return x + 7; }
__attribute__((visibility("default"))) callable volatile slot = target;
word bits(void) { return (word)slot; }
word tag(void) { return (word)slot & 15; }
unsigned equal_bits(word p) { return p == (word)slot; }
unsigned invoke(unsigned x) { return slot(x); }

__attribute__((nomicromips,noinline,aligned(16))) unsigned alternate(unsigned x) { return x + 19; }
word replace_callback(callable next) { callable previous = slot; slot = next; return (word)previous; }
